userscript.function:

$share.fn={};
for(var i in $shareFnNames){
    var fnName = $shareFnNames[i];
    $share.fn[fnName] = $sObject[fnName];
}

SUX.attachEvent('onActive', function() {
    $share.fn.doQuery();
});


$share.config = config;
var type = config.TYPE;
dataOutput.setValue('TYPE', type);
var splitedType = type.split('_');
for(var i in splitedType){
    if(splitedType[i].length > 1){
        splitedType[i] = splitedType[i].charAt(0).toUpperCase()+splitedType[i].substring(1).toLowerCase();
    }else if(splitedType[i].length == 1){
        splitedType[i] = splitedType[i].toUpperCase(); 
    }
}
type = splitedType.join('');
layoutObj.cells('a').attachURL('/Contract/Progress/ContractProgressList'+type+'.sux');
setTimeout(changeHeaderText, 0, 'a', Sepoa.cache.text.get('CT_101.TITLE_'+config.TYPE));


doServiceAjax('sepoa.svc.contract.SepoaContractService', 'CONNECTION', 'doGetScreenConfig', null, function(so) {
    if (so.status == 1) {
        $share.config.VIEW_OPTIONS = JSON.parse(so.result[0]);
    } else {
        AlertE(Sepoa.cache.text.get('CT_102.MESSAGE0002'));
    }
}, false);


var result = true;
var config = {
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    on: {
        callback: function(res, config, params) {
            if (!res.flag) {
                result = false;
                Alert(res.message);
            }
        }
    },
    contentType: "json",
    async: false
}

var params = $.extend(true, {
    module: "contract",
    action: action
}, data);

sUtils.multipart.send(config, params);
return result;


            var rId = tr.idd;
            var config = {
                url: window.CONTEXT_NAME + '/SepoaActionController.sux',
                on: {
                    callback: function(res, config, params) {
                        if(res.flag){
                            const itemData = res.result[0];
                            if(sUtils.string.isBlank(itemData) === false) {
                                for(const key in itemData){
                                    const cId = 'EXT_' + key;
                                    if(config.gridObj.columnIds.includes(cId)){
                                        config.gridObj.setCellValue(config.TARGET_ROW_ID, cId, itemData[key]);
                                    }
                                }
                            }

                            const rowData = gridObj.getRowDataObject(rId);
                            const contStatus = rowData['CONT_STATUS'];
                            if(contStatus == 'G') {
	                            const signerList = res.result[1];
	                            if(sUtils.string.isBlank(signerList) === false) {
	                                const targetSigner = signerList.find(e => e['SIGNER_ID'] == Sepoa.info.ID);
	                                if(targetSigner) {
	                                    const signStatus = sUtils.cache.combo.get(`SL0003,${Sepoa.info.HOUSE_CODE}#${Sepoa.info.LANGUAGE}#CT002`);
	                                    const {text, value} = signStatus.find(e => e['value'] == targetSigner['SIGN_FLAG'])
	                                    if(text) {
	                                        const targetCell = gridObj.cells(rId, gridObj.getColIndexById('CONT_STATUS'));
	                                        targetCell.cell.textContent = text;
	                                    }
	                                }
	                            }
                            }


                            if(callback){
                                try{
                                    callback(res, config, params);
                                }catch(e){
                                    console.error(e);
                                }
                            }
                        }
                    }
                },
                progress:false,
                gridObj:gridObj,
                TARGET_ROW_ID:rId
            }

            var params = {
                module: "contract",
                action: "doDocumentExtra",
                CONT_NO: gridObj.getCellValue(rId, 'CONT_NO'),
                CONT_GL_SEQ: gridObj.getCellValue(rId, 'CONT_GL_SEQ')
            };

            sUtils.multipart.send(config, params);


if(data.DATA_SOURCE == "MIGRATION"){
    sUtils.popup.modal({
        url:'/Contract/Migration/ContractMigrationView.sux',
        params:{
            CONT_NO:data.CONT_NO,
            CONT_GL_SEQ:data.CONT_GL_SEQ
        },
        title:sUtils.cache.text.get('POA_CONTRACT.TITLE_MIGRATION')
    })
}else if(data.DATA_SOURCE == "NEW"){
	callFunction('p', 'changeView', [{
        data: data,
        view: 'EDITOR'
    }]);            
}else{
    var status = data.CONT_STATUS;
    var view = 'VIEW';
    if (status == 'I' || status == 'R') {
        view = 'APPROVAL';
    } else if (status == 'RP') {
        view = 'REVIEW';
    } else if (['RA', 'RR'].includes(status)) {
        view = 'EDITOR';
    } else if (status == 'G' && data.CONT_METHOD != 'S') {
        view = 'SIGN';
    } else if (status == 'G' && data.CONT_METHOD == 'S') {
        view = 'SIGN';
    } else if (status == 'A') {
        view = 'COMPLETE';
    } else if (status == 'X' || status == 'K') {
        view = 'TERMINATION';
    } else if (status == 'T') {
        view = 'EDITOR';
        data = $.extend(true, {
            back: 'LIST'
        }, data);
    } else if (status == 'ALTER'){
        view = 'EDITOR'
    }

    callFunction('p', 'changeView', [{
        data: data,
        view: view
    }]);
}


if (dataArray.length == 0) {
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0005'));
    return;
}
if (dataArray.length > 1) {
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0006'));
    return;
}
for (var i in dataArray) {
    var contStatus = dataArray[i].CONT_STATUS;
    if (['T','C','G'].indexOf(contStatus) < 0) {
        Alert(Sepoa.cache.text.get('POA_CONTRACT.MESSAGE_0007'));
        return;
    }
}

